public class StringPoolDemo {
    public static void main(String[] args) {
        // Literals go to the pool
        String s1 = "hello";
        String s2 = "hello";

        // Both point to the SAME pooled object
        System.out.println(s1 == s2); // true - same reference

        // new String() creates a NEW heap object, NOT in pool
        String s3 = new String("hello");
        System.out.println(s1 == s3); // false - different objects
        System.out.println(s1.equals(s3)); // true - same content

        // intern() returns the pooled version
        String s4 = s3.intern();
        System.out.println(s1 == s4); // true - s4 now points to pool object
    }
}

import java.util.*;

public class InternDemo {
    public static void main(String[] args) {
        // Simulating reading status values from a database
        List<String> statuses = new ArrayList<>();
        for (int i = 0; i < 10000; i++) {
            // new String() forces heap allocation
            statuses.add(new String("PENDING"));
        }

        // Without intern: 10,000 separate objects
        String s1 = statuses.get(0);
        String s2 = statuses.get(1);
        System.out.println(s1 == s2); // false - different objects

        // With intern: all point to same pooled object
        var internedStatuses = statuses.stream()
            .map(String::intern)
            .toList();

        String i1 = internedStatuses.get(0);
        String i2 = internedStatuses.get(1);
        System.out.println(i1 == i2); // true - same pool reference
    }
}

public class PoolGarbageCollectionDemo {
    public static void main(String[] args) {
        // Create a string and intern it
        String dynamic = new String("temporary").intern();
        System.out.println("Pooled string created: " + dynamic);

        // Get the pooled reference
        String poolRef = dynamic.intern();
        System.out.println(poolRef == dynamic); // true - same pool object

        // Remove all references to the pooled string
        dynamic = null;
        poolRef = null;

        // Suggest GC (doesn't guarantee collection)
        System.gc();

        // In Java 7+, if no other references exist,
        // the pooled "temporary" string is now GC-eligible
        // In Java 6, it would remain in PermGen forever

        System.out.println("References cleared - pool entry is GC-eligible");
    }
}

public class StringConcatenationDemo {
    public static void main(String[] args) {
        // GOOD: Single expression - compiler optimizes to StringBuilder
        String name = "Alice";
        int age = 25;
        String result = "User: " + name + ", Age: " + age;
        // Compiles to: new StringBuilder().append("User: ").append(name)...

        // BAD: Loop concatenation - new StringBuilder per iteration!
        String output = "";
        for (int i = 0; i < 1000; i++) {
            output += "item" + i + ","; // New StringBuilder each time
        }

        // GOOD: Manual StringBuilder for loops
        var builder = new StringBuilder();
        for (int i = 0; i < 1000; i++) {
            builder.append("item").append(i).append(",");
        }
        String betterOutput = builder.toString();
    }
}
